     labelElement.setAttribute('x', x);
     labelElement.setAttribute('y', y);
-    labelElement.innerHTML = label;
+    labelElement.textContent = escapeHtml(label);
     return labelElement;
 };

 const renderShape = (shapeData) => {
     const shape = createElement(shapeData.type);

     // Sanitize all attributes before setting
     Object.keys(shapeData.attributes).forEach(key => {
         const value = shapeData.attributes[key];
         // Only set safe attributes, escape string values
         if (typeof value === 'string') {
             shape.setAttribute(key, escapeHtml(value));
         } else {
             shape.setAttribute(key, value);
         }
     });

     return shape;
 };

 const renderSprite = (sprite) => {
     const group = createElement('g');

     // Escape sprite name to prevent XSS
