         const nameElement = createElement('title');
         nameElement.textContent = escapeHtml(sprite.name);
         group.appendChild(nameElement);
     }

     // Render sprite text content safely
     if (sprite.text) {
         const textElement = renderText(sprite.text, sprite.x, sprite.y, sprite.fontSize, sprite.fontFamily);
         group.appendChild(textElement);
     }

     return group;
 };

 module.exports = {
     renderText,
     renderLabel,
     renderShape,
     renderSprite,
     escapeHtml
 };

