@@ -0,0 +1,35 @@
+// Security module for validating function names in Vega expressions
+// Prevents access to JavaScript built-ins and dangerous functions
+
+// Whitelist of allowed function names
+const ALLOWED_FUNCTIONS = new Set([
+  // Math functions
+  'abs', 'acos', 'asin', 'atan', 'atan2', 'ceil', 'cos', 'exp',
+  'floor', 'log', 'log10', 'max', 'min', 'pow', 'random', 'round',
+  'sin', 'sqrt', 'tan', 'trunc',
+  // String functions
+  'length', 'split', 'join', 'substr', 'substring', 'indexOf',
+  'lastIndexOf', 'trim', 'toLowerCase', 'toUpperCase',
+  // Array functions
+  'array', 'concat', 'slice', 'reverse', 'sort',
+  // Date functions
+  'date', 'year', 'month', 'day', 'hours', 'minutes', 'seconds',
+  'milliseconds', 'timezone',
+  // Type functions
+  'typeof', 'isdefined', 'isnull', 'isnumber', 'isstring', 'isarray',
+  'isobject', 'isboolean',
+  // Comparison functions
+  'equal', 'not', 'and', 'or', 'in', 'band',
+  // Other safe functions
+  'scale', 'signal', 'datum', 'view', 'width', 'height',
+  'pi', 'e', 'sqrt2', 'log2', 'log10', 'ln2', 'ln10'
+]);
+
+// Dangerous patterns that should never be allowed
+const DANGEROUS_PATTERNS = [
+  'constructor', 'prototype', '__proto__', 'eval', 'Function',
+  'global', 'window', 'document', 'location', 'navigator'
+];
+
+export function isSafeFunction(funcName) {
+  if (!funcName || typeof funcName !== 'string') {
+    return false;
+  }
+  
+  // Check for dangerous patterns
+  const lowerName = funcName.toLowerCase();
+  for (const pattern of DANGEROUS_PATTERNS) {
+    if (lowerName.includes(pattern)) {
+      return false;
+    }
+  }
+  
+  // Only allow whitelisted functions
+  return ALLOWED_FUNCTIONS.has(funcName);
+}

