+/**
+ * Strip HTML tags from a string value
+ * @param {string} value - The input string that may contain HTML
+ * @returns {string} - The sanitized string with HTML tags removed
+ */
+export function stripHtml(value) {
+  if (typeof value !== 'string') {
+    return value;
+  }
+
+  // Remove HTML tags using regex
+  // This strips all HTML tags while preserving text content
+  return value.replace(/<[^>]*>/g, '');
+}
+
