+/// Verify the certificate chain is valid and trusted
+pub fn verify_certificate_chain(cert_chain: &[Vec<u8>]) -> Result<()> {
+    if cert_chain.is_empty() {
+        return Err(Error::InvalidCertificateChain("Empty certificate chain".to_string()));
+    }
+
+    // Parse and validate each certificate in the chain
+    for (i, cert_bytes) in cert_chain.iter().enumerate() {
+        let (_, cert) = parse_x509_certificate(cert_bytes)
+            .map_err(|e| Error::InvalidCertificateChain(format!("Failed to parse certificate {}: {}", i, e)))?;
+        
+        // Verify certificate is not expired
+        let now = chrono::Utc::now();
+        if cert.validity().not_before > now || cert.validity().not_after < now {
+            return Err(Error::InvalidCertificateChain(format!("Certificate {} is expired or not yet valid", i)));
+        }
+        
+        // Verify certificate chain signature (except for root)
+        if i > 0 {
+            let (_, issuer_cert) = parse_x509_certificate(&cert_chain[i - 1])
+                .map_err(|e| Error::InvalidCertificateChain(format!("Failed to parse issuer certificate: {}", e)))?;
+            
+            issuer_cert.verify_signature(cert_bytes)
+                .map_err(|e| Error::InvalidCertificateChain(format!("Certificate {} signature verification failed: {}", i, e)))?;
+        }
+    }
+    
+    // Verify root certificate is trusted (self-signed)
+    let (_, root_cert) = parse_x509_certificate(&cert_chain[0])
+        .map_err(|e| Error::InvalidCertificateChain(format!("Failed to parse root certificate: {}", e)))?;
+    
+    root_cert.verify_self_signed()
+        .map_err(|e| Error::InvalidCertificateChain(format!("Root certificate verification failed: {}", e)))?;
+    
+    Ok(())
