+/*
+ * Redact sensitive authentication data from command documents
+ * This prevents information disclosure through command listeners
+ * CVE-2021-32050
+ */
+static void redact_sensitive_fields(zval *command)
+{
+    if (Z_TYPE_P(command) != IS_ARRAY) {
+        return;
+    }
+
+    HashTable *ht = Z_ARRVAL_P(command);
+    zval *field;
+    zend_string *key;
+    zend_ulong num_key;
+
+    /* Sensitive field names to redact */
+    const char *sensitive_fields[] = {
+        "password",
+        "pwd",
+        "credential",
+        "credentials",
+        NULL
+    };
+
+    ZEND_HASH_FOREACH_KEY_VAL(ht, num_key, key, field) {
+        if (key) {
+            for (int i = 0; sensitive_fields[i] != NULL; i++) {
+                if (strcmp(ZSTR_VAL(key), sensitive_fields[i]) == 0) {
+                    zval *redacted = zend_string_alloc(14, 0);
+                    ZVAL_STRINGL(redacted, "***REDACTED***", 14);
+                    zend_hash_update(ht, key, redacted);
+                    break;
+                }
+            }
+        }
+    } ZEND_HASH_FOREACH_END();
+}
+
+/*
+ * Create a command started event with redacted sensitive data
+ */
+static void create_command_started_event(zval *return_value, 
+                                         const char *database_name,
+                                         const char *command_name,
+                                         zval *command,
+                                         uint64_t request_id,
+                                         uint64_t operation_id,
+                                         zval *driver_info)
+{
+    /* Redact sensitive fields before creating event */
+    redact_sensitive_fields(command);
