+const crypto = require('crypto');
+
+const CSRF_SECRET_KEY = 'whistle-csrf-secret-' + crypto.randomBytes(32).toString('hex');
+
+function generateToken() {
+  return crypto.randomBytes(32).toString('hex');
+}
+
+function validateToken(token, secret) {
+  if (!token || !secret) return false;
+  const expected = crypto.createHmac('sha256', CSRF_SECRET_KEY).update(token + secret).digest('hex');
+  return crypto.timingSafeEqual(Buffer.from(token), Buffer.from(expected));
+}
+
+function createCsrfMiddleware() {
+  return function csrfMiddleware(req, res, next) {
+    const token = req.headers['x-csrf-token'] || req.body._csrf;
+    const secret = req.headers['x-csrf-secret'] || req.body._csrf_secret;
+
+    if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
+      return next();
+    }
+
+    if (!validateToken(token, secret)) {
+      return res.status(403).json({ error: 'CSRF token validation failed' });
+    }
+
+    next();
+  };
+}
+
+function generateCsrfPair() {
+  const token = generateToken();
+  const secret = generateToken();
+  return { token, secret };
+}
+
+module.exports = {
+  generateToken,
+  validateToken,
+  createCsrfMiddleware,
+  generateCsrfPair
+};
